#!/usr/bin/env pwsh
# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-21

<#
.SYNOPSIS
  Recipe: hot tar of one or more directories, in the order configured.
.DESCRIPTION
  A backup recipe. The engine passes a RecipeContext as -Recipe; this script
  registers one step, 'dump', which runs without stopping anything. It writes one
  uncompressed tar holding every DT_DIRS entry, in the order given: GNU tar writes
  members in command-line order. For stores where one part references another
  (a container registry: repositories before blobs), list the referencing part
  first.

  Parameters (service config env):
    DT_DIRS          absolute dirs, ';'-separated, archived in this order (required)
    DT_EXCLUDES      ';'-separated (optional). An entry starting with '/' is an
                     absolute path (anchored); any other entry is a name pattern
                     matched anywhere.
    DT_ARCHIVE_NAME  tar name (default: '<service>.tar')

  Members are stored relative to '/' (srv/app/data/...), with numeric owners:
  restore with 'tar --numeric-owner -xpf <tar> -C /' (or -C a scratch dir).

  A missing, relative or overlapping DT_DIRS entry is a validation problem: the
  service is skipped rather than backed up partly. tar exit 1 ("file changed as we
  read it", a file removed meanwhile) is a warning (live copy); exit >= 2 fails.
#>

param($Recipe)

if ($null -eq $Recipe) {
    Write-Host 'This is a sequencer recipe; it is loaded by the engine, not run directly.'
    return
}

# Shared by the step and the validate block (functions defined here would be out of
# scope when the engine later invokes a step). Returns the members (relative to '/'),
# the excludes, and the problems found.
$Recipe.State['DtPlan'] = {
    param($ctx)
    $split = { param($s) @($s.Split(';', [System.StringSplitOptions]::RemoveEmptyEntries) | ForEach-Object { $_.Trim() } | Where-Object { $_ }) }
    $problems = @()
    $dirs = @()
    foreach ($d in (& $split $ctx.EnvValue('DT_DIRS', ''))) {
        if (-not $d.StartsWith('/')) { $problems += "DT_DIRS entry not absolute: $d"; continue }
        $full = [System.IO.Path]::GetFullPath($d).TrimEnd('/')
        if (-not $full) { $problems += "DT_DIRS entry is the root: $d"; continue }
        if (-not (Test-Path -LiteralPath $full -PathType Container)) { $problems += "DT_DIRS entry missing or not a dir: $d"; continue }
        $dirs += $full
    }
    if ($dirs.Count -eq 0 -and $problems.Count -eq 0) { $problems += 'DT_DIRS not set' }
    for ($i = 0; $i -lt $dirs.Count; $i++) {
        for ($j = $i + 1; $j -lt $dirs.Count; $j++) {
            $a = $dirs[$i]; $b = $dirs[$j]
            if ($a -eq $b -or $a.StartsWith("$b/", [System.StringComparison]::Ordinal) -or $b.StartsWith("$a/", [System.StringComparison]::Ordinal)) {
                $problems += "DT_DIRS entries overlap: $a, $b"
            }
        }
    }
    $anchored = @()
    $unanchored = @()
    foreach ($e in (& $split $ctx.EnvValue('DT_EXCLUDES', ''))) {
        if ($e.StartsWith('/')) { $anchored += $e.Trim('/') } else { $unanchored += $e }
    }
    return @{ Members = @($dirs | ForEach-Object { $_.TrimStart('/') }); Anchored = $anchored; Unanchored = $unanchored; Problems = $problems }
}

$Recipe.AddStep('dump', {
    param($ctx)
    $plan = & $ctx.State['DtPlan'] $ctx
    if ($plan.Problems.Count -gt 0) { throw ($plan.Problems -join '; ') }
    New-Item -ItemType Directory -Force -Path $ctx.OutDir | Out-Null

    $name = $ctx.EnvValue('DT_ARCHIVE_NAME', "$($ctx.Service).tar")
    # GNU tar applies --anchored / --no-anchored to the excludes that follow them
    $tarArgs = @('--numeric-owner', '-C', '/', '--anchored')
    foreach ($e in $plan.Anchored) { $tarArgs += "--exclude=$e" }
    $tarArgs += '--no-anchored'
    foreach ($e in $plan.Unanchored) { $tarArgs += "--exclude=$e" }
    $tarArgs += @('-cf', (Join-Path $ctx.OutDir $name))
    $tarArgs += $plan.Members
    & tar @tarArgs
    if ($LASTEXITCODE -eq 1) {
        Write-Warning "$($ctx.Service) dump: some files changed while being read (expected for a live copy)"
    }
    elseif ($LASTEXITCODE -ne 0) {
        throw "tar of DT_DIRS failed (exit $LASTEXITCODE)"
    }
})

# preflight: Linux, tar, and DT_DIRS (set, absolute, existing, no overlap)
$Recipe.SetValidate({
    param($ctx)
    $problems = @()
    if (-not $IsLinux) { $problems += 'dir-tar runs on Linux only' }
    if (-not (Get-Command tar -CommandType Application -ErrorAction SilentlyContinue)) { $problems += 'tar not found' }
    $problems += @((& $ctx.State['DtPlan'] $ctx).Problems)
    return $problems
})
